sys_transform_entry.source_script:
answer = (function transformEntry(source) {
    const timeStamp = new Date().toISOString(); //performance.timeOrigin + performance.now();
    const infoStr = 'OHS - ' + timeStamp + ' - Row: ' + source.sys_import_row + ' - Create Hazard - Get HIRA Case - ';

    try {
        const posCode = source.u_position_code.toString(); //otherwise it's an object

        if (posCode !== null && posCode !== '') {
            //gs.debug(infoStr + '1- PosCode Exists: ' + posCode);
            const grPosCode = new GlideRecord('x_hccc_base_org_position_code');
            const grPosRep = new GlideRecord('x_hccc_hoc_ohs_position_reports_to');
            const grHira = new GlideRecord('x_hccc_hoc_ohs_hira_case');

            grPosCode.get('code', posCode); //should only have 1
            //gs.debug(infoStr + '2- grabbed grPosCode' + grPosCode.getUniqueValue());
            grPosRep.get('position_code', grPosCode.getUniqueValue());
            //gs.debug(infoStr + '3- grabbed grPosRep' + grPosRep.getUniqueValue());
            grHira.get('position_reporting_position', grPosRep.getUniqueValue());
            //gs.debug(infoStr + '4- grabbed grHira' + grHira.getUniqueValue());

            gs.debug(infoStr + '\nposCode: ' + posCode +
                ' - posCodeId: ' + grPosCode.getUniqueValue() +
                ' - PosRepId: ' + grPosRep.getUniqueValue() +
				' - HiraCaseId: ' + grHira.getUniqueValue()
            );
            return grHira.getUniqueValue();
        }
        /*else {
                   gs.warn(infoStr + 'PosCode is NULL');
                   gs.warn(infoStr + JSON.stringify(source));
               }*/
    } catch (e) {
        gs.error(infoStr + 'ERROR: ' + e);
        gs.error(infoStr + 'ERROR - source content: ' + JSON.stringify(source));
    }

    //return ""; //if there's no posCode we skip (reject)
})(source);
